A home-made connection pool batches queries and flushes them from one shared timer. Request handlers use AsyncLocalStorage for a request ID. What is logged, and what is the fix?

```js
const { AsyncLocalStorage } = require('node:async_hooks');
const als = new AsyncLocalStorage();
const queue = []; let timer = null;

function query(cb) {
  queue.push(cb);
  if (!timer) timer = setTimeout(() => {
    timer = null;
    queue.splice(0).forEach((f) => f());
  }, 5);
}

als.run('req-1', () => query(() => console.log('cb1', als.getStore())));
als.run('req-2', () => query(() => console.log('cb2', als.getStore())));
```

