This loader caches results. What does the script log?

```js
const cache = new Map();
function load(key, cb) {
  if (cache.has(key)) return cb(null, cache.get(key));
  setTimeout(() => { cache.set(key, 42); cb(null, 42); }, 5);
}

function test(label) {
  let x = 'before';
  load('k', () => console.log(label, x));
  x = 'after';
}

test('first');
setTimeout(() => test('second'), 20);
```

